import { showModal } from '@ui-kit/Modal';

import RecipeSelect from './index';
import { IRecipeCriteriaDTO } from '../../@types/recipes.backTypes';
import { IRecipe } from '../../@types/recipes.types';

export function selectRecipeAsync(
  criteria?: IRecipeCriteriaDTO,
  meta?: Record<number, Record<string, any>>,
): Promise<IRecipe> {
  return new Promise((resolve) => {
    showModal({
      title: 'Выбор блюда',
      size: 'xl',
      children: (closeHandler: () => void) => (
        <RecipeSelect
          criteria={criteria}
          onChange={(recipes) => {
            resolve(recipes[0]);
            closeHandler();
          }}
          meta={meta}
        />
      ),
    });
  });
}

export function selectSeveralRecipesAsync(criteria?: IRecipeCriteriaDTO): Promise<IRecipe[]> {
  return new Promise((resolve) => {
    showModal({
      title: 'Выбор блюд',
      size: 'xl',
      children: (closeHandler: () => void) => (
        <RecipeSelect
          criteria={criteria}
          multiple
          onChange={(recipes) => {
            resolve(recipes);
            closeHandler();
          }}
        />
      ),
    });
  });
}
