import React from 'react';

import EggFried from '@pohodnik/icons/svg/RealWorld/EggFried';

import { err } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import Empty from '@ui-kit/Empty';
import PohList from '@ui-kit/List';
import PohLoader from '@ui-kit/Loader';
import PohTabs, { IPohTab } from '@ui-kit/Tabs';

import RecipeListItemForSelect from './RecipeListItemForSelect';
import { getRecipesWithCategories } from '../../@services/recipes.service';
import { IRecipeCriteriaDTO } from '../../@types/recipes.backTypes';
import { IRecipe, IRecipesGroup } from '../../@types/recipes.types';

interface IRecipeSelectProps {
  onChange: (recipes: IRecipe[]) => void;
  criteria?: IRecipeCriteriaDTO;
  meta?: Record<number, Record<string, any>>;
  multiple?: boolean;
}

const RecipeSelect: React.FC<IRecipeSelectProps> = ({ criteria, onChange, meta, multiple }) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [recipesGroup, setRecipesGroup] = React.useState<IRecipesGroup[]>([]);
  const [selected, setSelected] = React.useState<IRecipe[]>([]);

  React.useEffect(() => {
    const init = async () => {
      try {
        setIsLoading(true);
        const rd = await getRecipesWithCategories(criteria);
        setRecipesGroup(rd);
      } catch (e) {
        err(e as Error);
      } finally {
        setIsLoading(false);
      }
    };

    init().catch(err);
  }, []);

  if (isLoading) {
    return (
      <div className="m-6 p-6 text-center">
        <PohLoader />
      </div>
    );
  }

  const tabs: IPohTab[] = recipesGroup.map((recGroup) => {
    return {
      key: recGroup.id,
      title: recGroup.name,
      content: (
        <div style={{ maxHeight: 460, overflowY: 'auto' }}>
          {recGroup.items.length === 0 && (
            <Empty icon={<EggFried />}>Нет рецептов в категории «{recGroup.name}»</Empty>
          )}
          <PohList
            flush
            data={recGroup.items.map((recipe) => {
              return {
                key: recipe.id,
                content: <RecipeListItemForSelect recipe={recipe} meta={meta?.[recipe.id]} />,
                action: true,
                onClick: () =>
                  multiple
                    ? selected.find((x) => x.id === recipe.id)
                      ? setSelected((cur) => cur.filter((x) => x.id !== recipe.id))
                      : setSelected((cur) => [...cur, recipe])
                    : onChange([recipe]),
                active: multiple && !!selected.find((x) => x.id === recipe.id),
                disabled: criteria?.exclude_ids?.includes(recipe.id),
              };
            })}
          />
        </div>
      ),
    };
  });

  return (
    <>
      <div style={{ maxHeight: 550, overflowY: 'auto' }}>
        <PohTabs tabs={tabs}></PohTabs>
      </div>
      {multiple && selected.length > 0 && (
        <footer className="mt-2 text-end">
          <PohButton onClick={() => onChange(selected)} variant={ButtonVariant.Primary}>
            Выбрать {selected.length}
          </PohButton>
        </footer>
      )}
    </>
  );
};

export default RecipeSelect;
