import { IHikingRecipeDTO } from '../@types/hiking.backendTypes';
import { IHikingRecipe } from '../@types/hiking.baseTypes';

export const mapHikingRecipe = (backData: IHikingRecipeDTO): IHikingRecipe => {
  return {
    id: +backData.id,
    recipe: {
      id: +backData.id_recipe,
      name: backData.name,
      promo: backData.promo_text,
      photo: backData.photo,
      id_author: +backData.id_author,
      water_count: backData.water_count ? +backData.water_count : null,
      gas_count: backData.gas_count ? +backData.gas_count : null,
      cooking_time: backData.cooking_time ? +backData.cooking_time : null,
    },
    category: {
      id: +backData.id_category,
      name: backData.category,
    },
  };
};
